class Solution {
    public int islandPerimeter(int[][] grid) {
        int land = 0, shared = 0;
        int m = grid.length, n = grid[0].length;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    land++;
                    if (i > 0 && grid[i - 1][j] == 1) shared++;
                    if (j > 0 && grid[i][j - 1] == 1) shared++;
                }
            }
        }
        return 4 * land - 2 * shared;
    }
}

