        q = deque([node])
        while q:
            cur = q.popleft()
            for neighbor in cur.neighbors:
                if neighbor not in mapping:
                    mapping[neighbor] = Node(neighbor.val)
                    q.append(neighbor)
        for orig, clone in mapping.items():
            clone.neighbors = [mapping[nbr] for nbr in orig.neighbors]
        return mapping[node]

