class Solution {
    public boolean canVisitAllRooms(List<List<Integer>> rooms) {
        int n = rooms.size();
        boolean[] visited = new boolean[n];
        Queue<Integer> q = new LinkedList<>();
        q.offer(0);
        visited[0] = true;
        int count = 1;
        while (!q.isEmpty()) {
            int cur = q.poll();
            for (int key : rooms.get(cur)) {
                if (!visited[key]) {
                    visited[key] = true;
                    count++;
                    q.offer(key);
                }
            }
        }
        return count == n;
    }
