import java.util.*;
class Solution {
    public int shortestBridge(int[][] grid) {
        int n = grid.length;
        List<int[]> island1 = new ArrayList<>();
        List<int[]> island2 = new ArrayList<>();
        boolean found = false;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    if (!found) {
                        dfs(grid, i, j, island1);
                        found = true;
                    } else if (grid[i][j] == 1) {
                        dfs(grid, i, j, island2);
                    }
                }
            }
        }
        int minD = Integer.MAX_VALUE;
        for (int[] p1 : island1) {
            for (int[] p2 : island2) {
                minD = Math.min(minD, Math.abs(p1[0] - p2[0]) + Math.abs(p1[1] - p2[1]) - 1);
            }
        }
        return minD;
    }
    private void dfs(int[][] g, int r, int c, List<int[]> list) {
        if (r < 0 || r >= g.length || c < 0 || c >= g.length || g[r][c] != 1) return;
        g[r][c] = 2;
        list.add(new int[]{r, c});
        dfs(g, r + 1, c, list);
        dfs(g, r - 1, c, list);
        dfs(g, r, c + 1, list);
        dfs(g, r, c - 1, list);
    }
}

