        dead = set(deadends)
        if "0000" in dead or target in dead:
            return -1
        if target == "0000":
            return 0
        begin_set = {"0000"}
        end_set = {target}
        steps = 0
        while begin_set and end_set:
            if len(begin_set) > len(end_set):
                begin_set, end_set = end_set, begin_set
            next_set = set()
            for cur in begin_set:
                for i in range(4):
                    digit = int(cur[i])
                    for diff in (1, -1):
                        nxt = cur[:i] + str((digit + diff) % 10) + cur[i+1:]
                        if nxt in end_set:
                            return steps + 1
                        if nxt not in dead:
                            dead.add(nxt)
                            next_set.add(nxt)
            begin_set = next_set
            steps += 1
        return -1

