    def findMinHeightTrees(self, n: int, edges: list[list[int]]) -> list[int]:
        if n <= 2: return list(range(n))
        adj = [set() for _ in range(n)]
        for u, v in edges:
            adj[u].add(v)
            adj[v].add(u)
        leaves = [i for i in range(n) if len(adj[i]) == 1]
        rem = n
        while rem > 2:
            rem -= len(leaves)
            new_leaves = []
            for leaf in leaves:
                nbr = adj[leaf].pop()
                adj[nbr].remove(leaf)
                if len(adj[nbr]) == 1:
                    new_leaves.append(nbr)
            leaves = new_leaves
        return leaves

